    final ObjectMapper json=new ObjectMapper();
    static Document doc(String id,String project,int version,String... texts){List<Page> pages=new ArrayList<>();for(int i=0;i<texts.length;i++)pages.add(new Page(i+1,texts[i],"PAGE","PDF",""));return new Document(id,project,"BID",id+".pdf",version,"hash-"+id,"",pages,cn.bidcheck.compat.Java8Api.listOf());}
    static Checkpoint cp(String id){return new Checkpoint(id,"报价","商务","HIGH","VALUE_COMPARE","amount","<=","100","元",true,true,true,null);}
    static Rule rule(){return new Rule("O1","报价","NUMBER","","amount","<=","100","元",cn.bidcheck.compat.Java8Api.mapOf(),"100","",cn.bidcheck.compat.Java8Api.listOf());}
    static Map<String,Object> number(Source source,String value){return linked("id","cached-number","kind","NUMBER","subject","","field","amount","rawValue",value,"value",value,"unit","元","basis","报价","scope","CURRENT_PROJECT","sourceIds",cn.bidcheck.compat.Java8Api.listOf(source.id()),"attributes",cn.bidcheck.compat.Java8Api.mapOf());}
    static Map<String,Object> source(EvidenceCorpus corpus,Source source){Document d=corpus.documents.stream().filter(x->x.id().equals(source.evidence().documentId())).findFirst().orElseThrow(java.util.NoSuchElementException::new);Page p=corpus.pages.get(EvidenceCorpus.pageKey(d.id(),source.evidence().page(),source.evidence().locationType()));return linked("id",source.id(),"evidence",source.evidence(),"projectId",d.projectId(),"documentHash",d.sha256(),"documentVersion",d.version(),"parserFingerprint",SharedFactReuse.parserFingerprint(p));}
    static Map<String,Object> entry(EvidenceCorpus corpus,Map<String,Object> fact){return linked("fact",fact,"sources",cn.bidcheck.compat.Java8Api.toList(corpus.all.stream().map(s->source(corpus,s))),"engineVersion",VERSION,"operationIdentity","operation");}
    SharedFactReuse reuse(EvidenceCorpus c,List<Map<String,Object>> entries){return new SharedFactReuse(c,cn.bidcheck.compat.Java8Api.mapOf("sharedFactLookup", (Function<Map<String,Object>,List<Map<String,Object>>>)(q)->entries),"model","engine");}
    @Test void compileOnlyRepairDoesNotLookupOperationsFieldsOrHistoricalFacts(){
        EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("d","p",1,"报价：80元")));AtomicInteger calls=new AtomicInteger();
        Function<Map<String,Object>,Object> callback=request->{calls.incrementAndGet();throw new AssertionError("No evidence lookup is required for a compiler-only target");};
        SharedFactReuse shared=new SharedFactReuse(c,cn.bidcheck.compat.Java8Api.mapOf("sharedFactLookup", callback, "evidenceOperationLookup", callback),"model","engine");
        assertTrue(shared.lookup(cn.bidcheck.compat.Java8Api.listOf(),c.all,cn.bidcheck.compat.Java8Api.listOf(),"REPAIR_REQUIREMENT").isEmpty());
        Rule unsupported=new Rule("u","未编译","UNSUPPORTED","","","","","",cn.bidcheck.compat.Java8Api.mapOf(),"原文","",cn.bidcheck.compat.Java8Api.listOf());
        assertTrue(shared.lookup(cn.bidcheck.compat.Java8Api.listOf(unsupported),c.all,cn.bidcheck.compat.Java8Api.listOf()).isEmpty());assertEquals(0,calls.get());assertEquals(0,shared.sharedPublishes);
    }
    @Test void repeatedLookupAdoptsOccurrenceOnceButEveryCheckpointStillRecordsUse(){
        EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("d","p",1,"报价：80元","补充说明")));List<Map<String,Object>> writes=new ArrayList<>();
        Map<String,Object> context=cn.bidcheck.compat.Java8Api.mapOf("sharedFactLookup", (Function<Map<String,Object>,?>)request->cn.bidcheck.compat.Java8Api.listOf(entry(c,number(c.all.get(0),"80"))), "sharedFactPublisher", (Consumer<Map<String,Object>>)writes::add);
        SharedFactReuse first=new SharedFactReuse(c,context,"model","engine");
        assertEquals(1,first.lookup(cn.bidcheck.compat.Java8Api.listOf(rule()),cn.bidcheck.compat.Java8Api.listOf(c.all.get(0)),cn.bidcheck.compat.Java8Api.listOf()).size());
        assertEquals(1,first.lookup(cn.bidcheck.compat.Java8Api.listOf(rule()),c.all,cn.bidcheck.compat.Java8Api.listOf(),"AFTER_FLIGHT").size());assertEquals(1,writes.size(),"Widening to unrelated candidates must not republish unchanged usage");
        assertEquals(1,new SharedFactReuse(c,context,"model","engine").lookup(cn.bidcheck.compat.Java8Api.listOf(rule()),c.all,cn.bidcheck.compat.Java8Api.listOf()).size());assertEquals(2,writes.size(),"A new checkpoint must retain its own audit dependency");
    }
    @Test void revalidatedLocalResponseSkipsModelButChangedOrConflictingSourceDoesNot()throws Exception{
        String project="北方新城中心综合楼二次装修工程",quote="质量\t合格。（见投标函）";
        Document tender=new Document("t","p","TENDER","招标文件",1,"tender-hash","",cn.bidcheck.compat.Java8Api.listOf(new Page(1,project,"BLOCK","TEXT",null), new Page(2,quote,"BLOCK","TEXT",null)),cn.bidcheck.compat.Java8Api.listOf());
        Checkpoint checkpoint=new Checkpoint("quality","质量响应","响应","HIGH","SEMANTIC_RESPONSE","compliance","RESPONDS",quote,"",true,true,true,new cn.bidcheck.domain.Domain.Evidence("t","招标文件",2,"BLOCK",quote,"p2",1));
        Map<String,Object> context=cn.bidcheck.compat.Java8Api.mapOf("tenderDocuments", cn.bidcheck.compat.Java8Api.listOf(tender), "originalRequirement", quote, "requirementProjectId", "p", "focusedCheck", true);
        Rule rule=new RequirementCompiler().compile(checkpoint,new RunSession(ModelGateway.disabled(),context,"test")).rules().get(0);
        String cover="（"+project+"）\n投标文件\n投标人：北方装饰有限公司",letter="3.投标函\n（"+project+"）投标文件\n质量为 合格 （填写“合格”）。\n投标人：北方装饰有限公司。";
        EvidenceCorpus corpus=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("bid","p",1,cover,letter)));
        SharedFactReuse reuse=new SharedFactReuse(corpus,cn.bidcheck.compat.Java8Api.mapOf(),"model","engine");RuleEvaluator evaluator=new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(),corpus,context);
        assertEquals("PASS",evaluator.evaluate(rule).status());assertTrue(reuse.extractionRules(cn.bidcheck.compat.Java8Api.listOf(rule),corpus.all,evaluator).isEmpty());
        assertTrue(reuse.completedReads().isEmpty(),"A program proof must never invent model read coverage");
        EvidenceCorpus conflict=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("bid","p",1,cover,letter,letter.replace("质量为 合格","质量为 不合格"))));
        assertEquals(1,new SharedFactReuse(conflict,cn.bidcheck.compat.Java8Api.mapOf(),"model","engine").extractionRules(cn.bidcheck.compat.Java8Api.listOf(rule),conflict.all,new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(),conflict,context)).size());
        Document changed=new Document(tender.id(),tender.projectId(),tender.role(),tender.name(),2,"changed-hash","",tender.pages(),cn.bidcheck.compat.Java8Api.listOf());
        assertEquals(1,reuse.extractionRules(cn.bidcheck.compat.Java8Api.listOf(rule),corpus.all,new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(),corpus,cn.bidcheck.compat.Java8Api.mapOf("tenderDocuments", cn.bidcheck.compat.Java8Api.listOf(changed)))).size());
    }
    @Test void visualRecoveryDoesNotInvalidateCanonicalTextManifestOrCauseUnboundedLookup(){
        EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("d","p",1,"报价：80元")));Source text=c.all.get(0);
        Source visual=new Source("Vimage",text.evidence(),text.opening(),false,false);
        AtomicInteger lookups=new AtomicInteger();
        Function<Map<String,Object>,List<Map<String,Object>>> callback=request->{
            lookups.incrementAndGet();assertEquals("CANONICAL_SOURCE",request.get("lookupMode"));
            assertEquals(false,request.get("includeOrigins"),"Realtime reuse does not load append-only historical origin rows");
            assertEquals(cn.bidcheck.compat.Java8Api.listOf(text.id()),request.get("sourceIds"));
            assertEquals(cn.bidcheck.compat.Java8Api.listOf(text.id()),cn.bidcheck.compat.Java8Api.toList(RuleEvaluator.maps(request.get("sources")).stream().map(row->str(row,"id"))));
            return cn.bidcheck.compat.Java8Api.listOf(entry(c,number(text,"80")));
        };
        SharedFactReuse shared=new SharedFactReuse(c,cn.bidcheck.compat.Java8Api.mapOf("sharedFactLookup", callback),"model","engine");
        assertEquals(1,shared.lookup(cn.bidcheck.compat.Java8Api.listOf(rule()),cn.bidcheck.compat.Java8Api.listOf(text, visual),cn.bidcheck.compat.Java8Api.listOf()).size());
        assertTrue(shared.lookup(cn.bidcheck.compat.Java8Api.listOf(rule()),cn.bidcheck.compat.Java8Api.listOf(visual),cn.bidcheck.compat.Java8Api.listOf()).isEmpty());
        assertEquals(1,lookups.get(),"A visual-only window must not become an empty-source full-document query");
    }
