    @Test void sameNamedPersonCannotBorrowAnotherEmployer(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("d","p",1,"姓名：同名甲\n注册证书\n单位名称：乙公司\n姓名：另一人\n单位名称：甲公司")));Map<String,Object> f=linked("id","certificate","kind","CERTIFICATE","subject","同名甲","field","certificate","rawValue","注册证书","value","注册证书","unit","","basis","","scope","CURRENT_PROJECT","sourceIds",cn.bidcheck.compat.Java8Api.listOf(c.all.get(0).id()),"attributes",cn.bidcheck.compat.Java8Api.mapOf("employer", "甲公司"));Rule r=new Rule("r","证书","CERTIFICATE","同名甲","","","","",cn.bidcheck.compat.Java8Api.mapOf("employer", "甲公司"),"证书","",cn.bidcheck.compat.Java8Api.listOf());assertTrue(reuse(c,cn.bidcheck.compat.Java8Api.listOf(entry(c,f))).lookup(cn.bidcheck.compat.Java8Api.listOf(r),c.all,cn.bidcheck.compat.Java8Api.listOf()).isEmpty());}
