    @Test void ignoresSectionAndQualityAndVisualFacts(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("d","p",1,"技术方案\n"+cn.bidcheck.compat.Java8Api.repeat("实质技术正文。", 20))));for(String kind:cn.bidcheck.compat.Java8Api.listOf("SECTION", "QUALITY")){Map<String,Object> f=number(c.all.get(0),"80");f.put("kind",kind);assertTrue(reuse(c,cn.bidcheck.compat.Java8Api.listOf(entry(c,f))).lookup(cn.bidcheck.compat.Java8Api.listOf(rule()),c.all,cn.bidcheck.compat.Java8Api.listOf()).isEmpty());}Map<String,Object> f=number(c.all.get(0),"80");f.put("sourceIds",cn.bidcheck.compat.Java8Api.listOf("Vimage"));assertTrue(reuse(c,cn.bidcheck.compat.Java8Api.listOf(entry(c,f))).lookup(cn.bidcheck.compat.Java8Api.listOf(rule()),c.all,cn.bidcheck.compat.Java8Api.listOf()).isEmpty());}
