    final class MemoryLedger {
        final List<Map<String,Object>> batches=new ArrayList<>();
        Map<String,Object> context(){return cn.bidcheck.compat.Java8Api.mapOf("sharedFactPublisher", (Consumer<Map<String,Object>>)batches::add, "sharedFactLookup", (Function<Map<String,Object>,List<Map<String,Object>>>)this::lookup);}
        List<Map<String,Object>> lookup(Map<String,Object> request){List<Map<String,Object>> out=new ArrayList<>();for(Map<String,Object> batch:batches){List<Map<String,Object>> facts=RuleEvaluator.maps(batch.get("facts"));for(Map<String,Object> fact:facts){Map<String,Object> item=linked("fact",fact,"sources",batch.get("sources"),"engineVersion",batch.get("engineVersion"),"observationPolicy",batch.getOrDefault("observationPolicy",""),"operationIdentity",batch.get("operationIdentity"),"batchId",batch.get("operationIdentity"),"coverageComplete",true,"fieldCoverage",batch.getOrDefault("fieldCoverage",cn.bidcheck.compat.Java8Api.listOf()),"fieldCoverageSources",batch.get("sources"));if(batch.containsKey("extractionCoverage"))item.put("extractionCoverage",batch.get("extractionCoverage"));out.add(item);}if(facts.isEmpty()&&batch.containsKey("fieldCoverage"))out.add(linked("recordType","FIELD_COVERAGE","engineVersion",batch.get("engineVersion"),"observationPolicy",batch.getOrDefault("observationPolicy",""),"batchId",batch.get("operationIdentity"),"fieldCoverage",batch.get("fieldCoverage"),"fieldCoverageSources",batch.get("sources")));}return out;}
    }
    ModelGateway numericModel(AtomicInteger extracts,boolean fail){return new ModelGateway(){public boolean enabled(){return true;}public String identity(){return "model";}public JsonNode request(String op,Map<String,Object> input)throws IOException{assertEquals("EXTRACT",op);extracts.incrementAndGet();if(fail)throw new IOException("unavailable");List<Map<String,Object>> facts=new ArrayList<>();for(Map<String,Object> row:RuleEvaluator.maps(input.get("sources"))){String quote=str(row,"quote");java.util.regex.Matcher m=java.util.regex.Pattern.compile("报价[：:]([0-9]+)元").matcher(quote);while(m.find())facts.add(linked("kind","NUMBER","subject","","field","amount","rawValue",m.group(1),"value",m.group(1),"unit","元","basis","报价","scope","CURRENT_PROJECT","sourceIds",cn.bidcheck.compat.Java8Api.listOf(str(row,"id")),"attributes",cn.bidcheck.compat.Java8Api.mapOf()));}return json.valueToTree(cn.bidcheck.compat.Java8Api.mapOf("facts", facts));}};}
    @Test void repeatedCheckpointRecomputesProofAndSkipsDuplicateExtraction(){MemoryLedger ledger=new MemoryLedger();AtomicInteger calls=new AtomicInteger();VerificationEngine e=new VerificationEngine(groundedPriceModel(calls,false),null);Document d=priceDoc("d","80");Map<String,Object> first=e.evaluate(priceCheckpoint("first"),cn.bidcheck.compat.Java8Api.listOf(d),null,ledger.context());assertEquals("PASS",first.get("businessDecision"),first.toString());Map<String,Object> context=new HashMap<>(ledger.context());context.put("priorSteps",first.get("steps"));Map<String,Object> second=e.evaluate(priceCheckpoint("second"),cn.bidcheck.compat.Java8Api.listOf(d),null,context);assertEquals("PASS",second.get("businessDecision"),second.toString());assertEquals(1,calls.get());Map<?,?> metrics=(Map<?,?>)second.get("metrics");assertEquals(1,metrics.get("reusedFacts"));assertEquals(1,metrics.get("extractionSkipped"));assertEquals(0,metrics.get("modelCalls"));assertTrue((Integer)metrics.get("sharedPublishes")>0,"adoption registers current checkpoint usage");}
