        Map<String,Object> factEntry=entry(corpus,factRow);factEntry.put("batchId","earliest-batch");factEntry.put("occurrenceId","occurrence-1");Map<String,Object> fieldEntry=independentFieldEntry(corpus,receipt,"later-batch");
        List<Map<String,Object>> adoptions=new ArrayList<>();SharedFactReuse reused=new SharedFactReuse(corpus,cn.bidcheck.compat.Java8Api.mapOf("sharedFactLookup", (Function<Map<String,Object>,?>)q->cn.bidcheck.compat.Java8Api.listOf(factEntry, fieldEntry), "sharedFactPublisher", (Consumer<Map<String,Object>>)adoptions::add),"model","engine");
