        java.util.Map<java.lang.String, java.lang.Object> adopted=RuleEvaluator.maps(adoptions.get(0).get("fieldCoverage")).get(0);assertEquals(cn.bidcheck.compat.Java8Api.listOf(facts.get(0).id()),adopted.get("factIds"));assertEquals(false,adopted.get("observedInCurrentRun"));
