    ModelGateway groundedPriceModel(AtomicInteger extracts,boolean fail){return new ModelGateway(){
        public boolean enabled(){return true;}public String identity(){return "grounded-price-cache-fixture";}
        public JsonNode request(String op,Map<String,Object> input)throws IOException{
            if(op.equals("COMPILE"))return json.valueToTree(cn.bidcheck.compat.Java8Api.mapOf("logic", "ALL", "rules", cn.bidcheck.compat.Java8Api.listOf(linked("id","O1","description","报价","predicate","NUMBER","subject","甲公司","field","amount","operator","<=","expected","100","unit","元","sourceQuote",PRICE_REQUIREMENT,"parameters",cn.bidcheck.compat.Java8Api.mapOf("lot", "不划分标段", "currency", "人民币", "amountBasis", "投标总报价", "taxBasis", "含税")))));
            assertEquals("EXTRACT",op);extracts.incrementAndGet();if(fail)throw new IOException("unavailable");List<Map<String,Object>> facts=new ArrayList<>();
            for(Map<String,Object> row:RuleEvaluator.maps(input.get("sources"))){java.util.regex.Matcher m=java.util.regex.Pattern.compile("投标总报价[：:]([0-9]+)元").matcher(str(row,"quote"));while(m.find())facts.add(linked("kind","NUMBER","subject","甲公司","field","amount","rawValue",m.group(1),"value",m.group(1),"unit","元","basis","投标总报价","scope","CURRENT_PROJECT","sourceIds",cn.bidcheck.compat.Java8Api.listOf(str(row,"id")),"attributes",cn.bidcheck.compat.Java8Api.mapOf("lot", "不划分标段", "currency", "人民币", "taxBasis", "含税")));}
            return json.valueToTree(cn.bidcheck.compat.Java8Api.mapOf("facts", facts));
        }
    };}
