    Map<String,Object> processingOccurrence(EvidenceCorpus corpus,Source original,String quote){
        Map<String,Object> stored=new LinkedHashMap<>(source(corpus,original));stored.put("id","P1");
        cn.bidcheck.domain.Domain.Evidence evidence=original.evidence();stored.put("evidence",new cn.bidcheck.domain.Domain.Evidence(evidence.documentId(),evidence.documentName(),evidence.page(),evidence.locationType(),quote,"native-field:amount",0));
        Map<String,Object> fact=number(original,"80");fact.put("sourceIds",cn.bidcheck.compat.Java8Api.listOf("P1"));
        return linked("occurrenceId","page-occurrence","projectId",stored.get("projectId"),"fact",fact,"sources",cn.bidcheck.compat.Java8Api.listOf(stored),"engineVersion","page-facts-1");
    }
